export function checklistMarkdown():string {
  return ['# Engine capabilities','',`Reviewed: ${capabilityReviewDate}. Scope inventory, not an individual-run certificate.`,
    '','Source: frontend/app/checklist/datos.ts. The live page and download use this same registry.','',
    ...engineCapabilities.flatMap(area=>[`## ${area.name}`,'',`Workspace: ${area.workspace}`,'',
      ...area.available.map(item=>`- [x] ${item}`),...area.pending.map(item=>`- [ ] ${item}`),
      ...area.deferred.map((item:string)=>`- [ ] *Deferred:* ${item}`),''])].join('\n');
}

